{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Top 10 Tournaments by Number of Matches",
  "data": {"url": "results.csv"},
  "transform": [
    {"aggregate": [{"op": "count", "as": "matches"}], "groupby": ["tournament"]},
    {"window": [{"op": "rank", "as": "rank"}], "sort": [{"field": "matches", "order": "descending"}]},
    {"filter": "datum.rank <= 10"}
  ],
  "mark": "bar",
  "encoding": {
    "y": {"field": "tournament", "type": "nominal", "sort": "-x", "title": "Tournament"},
    "x": {"field": "matches", "type": "quantitative", "title": "Number of Matches"}
  }
}

